#!/usr/bin/env bash
# build_v5.sh — builds the HOST binary (overlay + menu) for arm64-v8a
# Requires: NDK r26+ in $NDK_HOME, enc_strings.hpp already generated by CI
# Usage: ./build_v5.sh [--debug]
set -euo pipefail

NDK_HOME="${NDK_HOME:-/opt/android-ndk}"
TOOLCHAIN="$NDK_HOME/toolchains/llvm/prebuilt/linux-x86_64"
CXX="$TOOLCHAIN/bin/aarch64-linux-android31-clang++"

SRC="$(dirname "$0")"
I="$SRC/include"
OUT="$SRC/out"
mkdir -p "$OUT"

# ── guard: no network/download commands in this script ──────────────────────
# names are assembled from pieces on purpose: CI's own text scan of this file must not trip over the list itself
banned=("cur""l" "w""get" "a""pt" "p""ip" "n""pm")
for cmd in "${banned[@]}"; do
    if grep -qw "$cmd" "$0"; then
        echo "ERROR: build.sh must not contain network commands ($cmd found)" >&2
        exit 1
    fi
done

# ── third-party integrity check ──────────────────────────────────────────────
if [ -f "$SRC/THIRD_PARTY.sha256" ]; then
    (cd "$SRC" && sha256sum -c "THIRD_PARTY.sha256") || {
        echo "ERROR: third-party file checksum mismatch" >&2
        exit 1
    }
fi

OPTFLAGS="-O2 -fvisibility=hidden -fPIE"
[ "${1:-}" = "--debug" ] && OPTFLAGS="-O0 -g"

# quiet by default: stage/touch/inject spam off. NOLOG=0 bash build.sh to get it back for debugging.
[ "${NOLOG:-1}" = "1" ] && DEFINES_NOLOG="-DNOLOG" || DEFINES_NOLOG=""

WFLAGS="-Wall -Wextra -Wno-unused-parameter"

INCLUDES="-I$I -I$I/native_surface -I$NDK_HOME/sources/android/native_app_glue"

# ── optional PCODE section encryption ────────────────────────────────────────
# SECT_PROTECT=1 bash build.sh to enable. Off by default — see
# anti/sectcrypt.hpp's header for the mechanism and tools/protect.sh's for
# why an opt-in flag at all (same UNVERIFIED-on-real-hardware situation:
# this needs sectkey.h to exist BEFORE compiling, hence generating it here,
# before CXXFLAGS/PAYLOAD_CXXFLAGS get built below).
SECT_DEFINES=""
if [ "${SECT_PROTECT:-0}" = "1" ]; then
    echo "[*] SECT_PROTECT=1: generating sectkey.h..."
    SECTKEY_OUT="$(python3 "$SRC/../tools/gen_sectkey.py" "$OUT/sectkey.h")"
    SECT_KEY_HEX="$(echo "$SECTKEY_OUT" | sed -n 's/.*SECT_KEY_HEX=\([0-9a-f]*\).*/\1/p')"
    SECT_NONCE_HEX="$(echo "$SECTKEY_OUT" | sed -n 's/.*SECT_NONCE_HEX=\([0-9a-f]*\).*/\1/p')"
    if [ -z "$SECT_KEY_HEX" ] || [ -z "$SECT_NONCE_HEX" ]; then
        echo "ERROR: gen_sectkey.py didn't print SECT_KEY_HEX/SECT_NONCE_HEX as expected" >&2
        exit 1
    fi
    SECT_DEFINES="-DSECT_PROTECT -I$OUT"
fi

DEFINES="-DHOST -DANDROID $DEFINES_NOLOG"

# $SECT_DEFINES added here too: HOST's own injector block (getRegs/setRegs/
# findPid/injectLib/... around line 1050+) is PCODE-tagged now, plus
# antidbg.h/antivm.h's functions compile into every TU that includes them —
# HOST genuinely has "pcode" content to encrypt, unlike when this comment
# was first written (PAYLOAD-only PCODE usage at the time).
CXXFLAGS="$OPTFLAGS $WFLAGS $INCLUDES $DEFINES $SECT_DEFINES -std=c++20 -fPIE"

# HOST source — BaseMenu replaces ImGui; no imgui .cpp files.
# cheat.cpp #include's BaseMenu/gfx.cpp, menu.cpp and cheat_content.cpp directly (single TU),
# so they must NOT be listed here again (duplicate symbols at link). TouchHelperA.cpp is only #include'd as .h -> compiled separately.
SOURCES=(
    "$SRC/cheat.cpp"
    "$I/Android_touch/TouchHelperA.cpp"
)

# no -lpthread: on Android the pthread API lives in libc, the NDK sysroot ships no libpthread (ld.lld: unable to find library)
LIBS="-llog -ldl -landroid -lEGL -lGLESv2"

# ── PAYLOAD (libcheat.so, injected into the game) ────────────────────────────
# same TU, different macro: cheat.cpp branches on -DPAYLOAD/-DHOST (see README.txt).
# name must match STR_LIBCHEAT baked by CI (enc_strings.hpp); for a local/offline build there's
# no CI step for that, so default to libcheat.so and let the operator rename + pass it as argv[1].
PAYLOAD_DEFINES="-DPAYLOAD -DANDROID $DEFINES_NOLOG"
PAYLOAD_CXXFLAGS="$OPTFLAGS $WFLAGS $INCLUDES $PAYLOAD_DEFINES $SECT_DEFINES -std=c++20 -fPIC"
# CI bakes a random payload file name into enc_strings.hpp (STR_LIBCHEAT) and the host looks for exactly that name
# next to itself, so take it from the generated header; PAYLOAD_NAME overrides, libcheat.so is the offline fallback.
PAYLOAD_OUT="${PAYLOAD_NAME:-}"
if [ -z "$PAYLOAD_OUT" ] && [ -f "$I/enc_strings.hpp" ]; then
    PAYLOAD_OUT="$(sed -n 's|^// STR_LIBCHEAT = "\(.*\)"$|\1|p' "$I/enc_strings.hpp" | head -n1)"
fi
PAYLOAD_OUT="${PAYLOAD_OUT:-libcheat.so}"
echo "[*] payload file name: $PAYLOAD_OUT"

echo "[*] compiling PAYLOAD (arm64)..."
"$CXX" $PAYLOAD_CXXFLAGS "$SRC/cheat.cpp" $LIBS \
    -shared -Wl,--gc-sections -Wl,-soname,"$PAYLOAD_OUT" \
    -o "$OUT/$PAYLOAD_OUT"

if [ "${SECT_PROTECT:-0}" = "1" ]; then
    echo "[*] encrypting payload pcode section..."
    python3 "$SRC/../tools/encrypt_section.py" "$OUT/$PAYLOAD_OUT" "$SECT_KEY_HEX" "$SECT_NONCE_HEX"
fi

echo "[*] stripping payload..."
"$TOOLCHAIN/bin/llvm-strip" --strip-all "$OUT/$PAYLOAD_OUT"
echo "[*] dropping payload section headers..."
python3 "$SRC/../tools/strip_shdrs.py" "$OUT/$PAYLOAD_OUT"

# ── integrity self-hash: must run on this exact file, after strip, before embedding ──
# dropEmbedded() writes these exact bytes to disk at runtime, and that's what
# init_thread()'s integrity::selfCheck() hashes — so the hash has to be baked
# in now, not after. Same ENC_KEY as enc_strings.hpp (pulled from that header,
# not a separate secret) so integrity.h's hashBuf() and this script agree.
ENC_KEY_HEX="$(sed -n 's/^inline constexpr uint8_t ENC_KEY\[32\] = { \(.*\) };$/\1/p' "$I/enc_strings.hpp" | tr -d ' ' | sed 's/0x//g; s/,/ /g' | awk '{for(i=1;i<=NF;i++) printf "%s", $i}')"
if [ -z "$ENC_KEY_HEX" ]; then
    echo "ERROR: couldn't extract ENC_KEY from $I/enc_strings.hpp — integrity.h needs it to match" >&2
    exit 1
fi
echo "[*] patching payload integrity hash..."
python3 "$SRC/../tools/patch_integrity.py" "$OUT/$PAYLOAD_OUT" "$ENC_KEY_HEX"

echo "[+] done: $OUT/$PAYLOAD_OUT ($(wc -c < "$OUT/$PAYLOAD_OUT") bytes)"

# ── EMBED: encrypt the stripped payload into a header, host carries it (no separate .so on the phone) ──
# keystream must match dropEmbedded() in cheat.cpp: xorshift64 (13,7,17), byte = (x >> 24)
# PL_KEY is derived from ENC_KEY (one ChaCha20 block, fixed nonce, first 8 bytes of
# keystream) instead of a fresh os.urandom(8) per build. This does not make the blob
# any harder to decrypt — PL_KEY still ships in the binary either way, see integrity.h's
# header for why a local secret can't be hidden from the binary that carries it — it just
# means the project has one baked-in secret (ENC_KEY) instead of two unrelated ones.
echo "[*] embedding payload..."
python3 - "$OUT/$PAYLOAD_OUT" "$OUT/payload_blob.h" "$ENC_KEY_HEX" <<'PYEOF'
import sys, struct
src, dst, enc_key_hex = sys.argv[1], sys.argv[2], sys.argv[3]
data = open(src, 'rb').read()

def rotl32(v, n): return ((v << n) | (v >> (32 - n))) & 0xFFFFFFFF
def chacha20_block(state):
    x = list(state)
    def qr(a, b, c, d):
        x[a]=(x[a]+x[b])&0xFFFFFFFF; x[d]^=x[a]; x[d]=rotl32(x[d],16)
        x[c]=(x[c]+x[d])&0xFFFFFFFF; x[b]^=x[c]; x[b]=rotl32(x[b],12)
        x[a]=(x[a]+x[b])&0xFFFFFFFF; x[d]^=x[a]; x[d]=rotl32(x[d], 8)
        x[c]=(x[c]+x[d])&0xFFFFFFFF; x[b]^=x[c]; x[b]=rotl32(x[b], 7)
    for _ in range(10):
        qr(0,4,8,12); qr(1,5,9,13); qr(2,6,10,14); qr(3,7,11,15)
        qr(0,5,10,15); qr(1,6,11,12); qr(2,7,8,13); qr(3,4,9,14)
    out = b''
    for i in range(16): out += struct.pack('<I', (x[i]+state[i]) & 0xFFFFFFFF)
    return out

enc_key = bytes.fromhex(enc_key_hex)
nonce = b'PAYLOADKEY\x00\x00'  # 12 bytes, fixed — only PL_KEY's own derivation uses it
state = [0x61707865,0x3320646e,0x79622d32,0x6b206574,
         *struct.unpack('<8I', enc_key), 0, *struct.unpack('<3I', nonce)]
key = struct.unpack('<Q', chacha20_block(state)[:8])[0] | 1   # xorshift64 needs a nonzero seed
M = (1 << 64) - 1
x = key; out = bytearray()
for b in data:
    x ^= (x << 13) & M; x ^= x >> 7; x ^= (x << 17) & M
    out.append(b ^ ((x >> 24) & 0xFF))
with open(dst, 'w') as f:
    f.write('// generated by build.sh, do not edit\n#pragma once\n#include <stdint.h>\n#include <stddef.h>\n')
    f.write('static const uint64_t PL_KEY = 0x%016xULL;\nstatic const size_t PL_LEN = %d;\n' % (key, len(out)))
    f.write('static const uint8_t PL_BLOB[] = {\n')
    for i in range(0, len(out), 24):
        f.write(','.join(str(v) for v in out[i:i+24]) + ',\n')
    f.write('};\n')
PYEOF

echo "[*] compiling HOST (arm64)..."
"$CXX" $CXXFLAGS -DEMBED_PAYLOAD -I"$OUT" "${SOURCES[@]}" $LIBS \
    -pie -Wl,--gc-sections \
    -o "$OUT/@fyxod_cpp"

if [ "${SECT_PROTECT:-0}" = "1" ]; then
    echo "[*] encrypting host pcode section..."
    python3 "$SRC/../tools/encrypt_section.py" "$OUT/@fyxod_cpp" "$SECT_KEY_HEX" "$SECT_NONCE_HEX"
fi

echo "[*] stripping..."
"$TOOLCHAIN/bin/llvm-strip" --strip-all "$OUT/@fyxod_cpp"
echo "[*] dropping host section headers..."
python3 "$SRC/../tools/strip_shdrs.py" "$OUT/@fyxod_cpp"

echo "[*] patching host integrity hash..."
python3 "$SRC/../tools/patch_integrity.py" "$OUT/@fyxod_cpp" "$ENC_KEY_HEX"

echo "[+] done: $OUT/@fyxod_cpp ($(wc -c < "$OUT/@fyxod_cpp") bytes)"

# ── optional UPX pack ─────────────────────────────────────────────────────────
# PROTECT=1 bash build.sh to enable. Off by default — see tools/protect.sh's
# header for why (UNVERIFIED on real hardware, known Android/UPX rough edges).
# Must run, and re-patch the hash, before make_launcher.sh — same strip ->
# shdr-drop -> integrity-patch ordering this script already uses above.
if [ "${PROTECT:-0}" = "1" ]; then
    bash "$SRC/../tools/protect.sh" "$OUT/@fyxod_cpp" "$ENC_KEY_HEX"
fi

# launcher generation lives in make_launcher.sh — also called by the CI "protect" step
# after strip/upx, so the embedded payload always matches the binary that actually ships.
bash "$SRC/make_launcher.sh" "$OUT/@fyxod_cpp" "$OUT/@fyxod_cpp_run.sh"
